args.command:
node -e '
// Test continuous ramp curve & physics trajectory
const DEG = Math.PI / 180;
const THETA_MAX = 115 * DEG;
const TARGET_HEIGHT = 20.0;

function rawCurvatureWeight(u) {
  const u0 = 0.22;
  const entry = u < u0 ? (u / u0) * (u / u0) * (3 - 2 * (u / u0)) : 1.0;
  const hookBoost = 1.0 + 0.45 * Math.pow(Math.max(0, (u - 0.55) / 0.45), 1.5);
  return entry * hookBoost;
}

const N = 2000;
const thetaArr = new Float64Array(N + 1);
let integralF = 0;
for (let i = 1; i <= N; i++) {
  const u = (i - 0.5) / N;
  integralF += rawCurvatureWeight(u) / N;
  thetaArr[i] = integralF;
}
for (let i = 0; i <= N; i++) {
  thetaArr[i] = (thetaArr[i] / integralF) * THETA_MAX;
}
let unitX = 0, unitY = 0;
for (let i = 1; i <= N; i++) {
  const th = 0.5 * (thetaArr[i - 1] + thetaArr[i]);
  unitX += Math.cos(th) / N;
  unitY += Math.sin(th) / N;
}
const L = TARGET_HEIGHT / unitY;
console.log("Ramp arc length L =", L.toFixed(3), "m, Lip X =", (L * unitX).toFixed(3), "m, Lip Y =", (L * unitY).toFixed(3), "m");

let x = 0, y = 0, maxX = 0, yAtMaxX = 0;
for (let i = 1; i <= N; i++) {
  const ds = L / N;
  const th = 0.5 * (thetaArr[i - 1] + thetaArr[i]);
  x += Math.cos(th) * ds;
  y += Math.sin(th) * ds;
  if (x > maxX) { maxX = x; yAtMaxX = y; }
}
console.log("Max X (vertical wall) =", maxX.toFixed(3), "m at Y =", yAtMaxX.toFixed(3), "m, Lip overhang =", (maxX - x).toFixed(3), "m");
'

