args.command:
node -e '
const DEG = Math.PI / 180;
const THETA_MAX = 115 * DEG;
const TARGET_HEIGHT = 20.0;

// Let curvature be smooth C2 entry, strong lower curve to 75 deg, tall near-vertical rise, and pronounced hook to 115 deg
function rawCurvatureWeight(u) {
  const u0 = 0.14;
  const entry = u < u0 ? (u / u0) * (u / u0) * (3 - 2 * (u / u0)) : 1.0;
  // Slightly less curvature around u=0.55 (the tall vertical section) and stronger curvature at bottom (u~0.25) and top hook (u>0.75)
  const midDip = 1.0 - 0.38 * Math.exp(-Math.pow((u - 0.52) / 0.18, 2));
  const hookBoost = 1.0 + 0.55 * Math.pow(Math.max(0, (u - 0.68) / 0.32), 1.4);
  return entry * midDip * hookBoost;
}

const N = 2000;
const thetaArr = new Float64Array(N + 1);
let integralF = 0;
for (let i = 1; i <= N; i++) {
  const u = (i - 0.5) / N;
  integralF += rawCurvatureWeight(u) / N;
  thetaArr[i] = integralF;
}
for (let i = 0; i <= N; i++) thetaArr[i] = (thetaArr[i] / integralF) * THETA_MAX;
let unitX = 0, unitY = 0;
for (let i = 1; i <= N; i++) {
  const th = 0.5 * (thetaArr[i - 1] + thetaArr[i]);
  unitX += Math.cos(th) / N;
  unitY += Math.sin(th) / N;
}
const L = TARGET_HEIGHT / unitY;
let x = 0, y = 0, maxX = 0, yAtMaxX = 0, minR = 999;
for (let i = 1; i <= N; i++) {
  const ds = L / N;
  const th = 0.5 * (thetaArr[i - 1] + thetaArr[i]);
  const kappa = (thetaArr[i] - thetaArr[i - 1]) / ds;
  if (i > N * 0.15 && 1 / kappa < minR) minR = 1 / kappa;
  x += Math.cos(th) * ds;
  y += Math.sin(th) * ds;
  if (x > maxX) { maxX = x; yAtMaxX = y; }
}
console.log("L =", L.toFixed(2), "Lip X =", x.toFixed(2), "Lip Y =", y.toFixed(2), "MaxX =", maxX.toFixed(2), "at Y =", yAtMaxX.toFixed(2), "Overhang =", (maxX - x).toFixed(2), "minR =", minR.toFixed(2));
'

