// Minimal 3D vec/quat helper to test exact rigid body equations
function v3(x=0,y=0,z=0){ return {x,y,z}; }
function add(a,b){ return {x:a.x+b.x, y:a.y+b.y, z:a.z+b.z}; }
function sub(a,b){ return {x:a.x-b.x, y:a.y-b.y, z:a.z-b.z}; }
function scale(a,s){ return {x:a.x*s, y:a.y*s, z:a.z*s}; }
function dot(a,b){ return a.x*b.x + a.y*b.y + a.z*b.z; }
function cross(a,b){ return {x:a.y*b.z-a.z*b.y, y:a.z*b.x-a.x*b.z, z:a.x*b.y-a.y*b.x}; }
function qMul(a,b){
  return {
    x: a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
    y: a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
    z: a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w,
    w: a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z
  };
}
function qConj(q){ return {x:-q.x, y:-q.y, z:-q.z, w:q.w}; }
function qNorm(q){
  const l = Math.hypot(q.x,q.y,q.z,q.w)||1;
  return {x:q.x/l, y:q.y/l, z:q.z/l, w:q.w/l};
}
function qRot(q, v){
  const u = {x:q.x, y:q.y, z:q.z};
  const s = q.w;
  const d = dot(u, v);
  const c = cross(u, v);
  return {
    x: 2*d*u.x + (s*s - dot(u,u))*v.x + 2*s*c.x,
    y: 2*d*u.y + (s*s - dot(u,u))*v.y + 2*s*c.y,
    z: 2*d*u.z + (s*s - dot(u,u))*v.z + 2*s*c.z
  };
}

function runTest(cfg) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceN = (cfg.maxDownforceKg ?? 4700) * 9.81;
  const driveScale = (cfg.entrySpeed ?? 100) / 100;
  const totalThrusterN = (cfg.thrusterForceKg ?? 6500) * 9.81;
  const g = cfg.gravity ?? 9.81;

  // Inertia in local frame
  const Ilocal = { x: 0.48 * mass, y: 1.90 * mass, z: 1.65 * mass };

  let pos = v3(-6.5, 0.36, 0);
  let vel = v3(0, 0, 0);
  let quat = { x: 0, y: 0, z: 0, w: 1 };
  let omegaLocal = v3(0, 0, 0); // angular velocity in body frame

  const wheels = [
    { name: "FL", lx: 1.38, ly: -0.18, lz: -0.84, comp: 0 },
    { name: "FR", lx: 1.38, ly: -0.18, lz: +0.84, comp: 0 },
    { name: "RL", lx: -1.38, ly: -0.18, lz: -0.84, comp: 0 },
    { name: "RR", lx: -1.38, ly: -0.18, lz: +0.84, comp: 0 },
  ];

  // Nozzles: each has local position and local jet direction (force on body = -jetDir * thrust)
  const nozzles = [
    { id: "downFL", pos: v3(1.32, -0.30, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downFR", pos: v3(1.32, -0.30, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRL", pos: v3(-1.32, -0.30, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRR", pos: v3(-1.32, -0.30, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    // Side attitude nozzles on upper flanks: jet shoots outward+upward in car frame
    { id: "sideFL", pos: v3(1.10, 0.22, -0.95), jet: v3(0, 0.8, -0.6), thrust: 0 },
    { id: "sideFR", pos: v3(1.10, 0.22, +0.95), jet: v3(0, 0.8, +0.6), thrust: 0 },
    { id: "sideRL", pos: v3(-1.10, 0.22, -0.95), jet: v3(0, 0.8, -0.6), thrust: 0 },
    { id: "sideRR", pos: v3(-1.10, 0.22, +0.95), jet: v3(0, 0.8, +0.6), thrust: 0 },
    // Rear diffuser nozzles: jet shoots backward (-X)
    { id: "rear1", pos: v3(-2.22, -0.14, -0.36), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear2", pos: v3(-2.22, -0.14, -0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear3", pos: v3(-2.22, -0.14, +0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear4", pos: v3(-2.22, -0.14, +0.36), jet: v3(-1, 0, 0), thrust: 0 },
  ];

  let phase = "READY";
  let holdStartTime = -1;
  let releaseTime = -1;
  let touchdownTime = -1;
  let maxImpactForce = 0;
  const sHold = ramp.L - 2.35; // target stop near lip (~26.1 m, theta ~ 111.5 deg)
  const dt = 1 / 120;

  for (let step = 0; step <= 16 * 120; step++) {
    const t = step * dt;
    let Fworld = v3(0, -mass * g, 0);
    let Tlocal = v3(0, 0, 0);

    function applyWorldForceAtLocalPoint(Fw, rLocal) {
      Fworld = add(Fworld, Fw);
      const Flocal = qRot(qConj(quat), Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }
    function applyLocalForceAtLocalPoint(Flocal, rLocal) {
      const Fw = qRot(quat, Flocal);
      Fworld = add(Fworld, Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }

