    { id: "downFL", pos: v3(1.32, -0.30, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downFR", pos: v3(1.32, -0.30, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRL", pos: v3(-1.32, -0.30, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRR", pos: v3(-1.32, -0.30, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    // Side attitude nozzles on upper flanks: jet shoots outward+upward in car frame
    { id: "sideFL", pos: v3(1.10, 0.22, -0.95), jet: v3(0, 0.8, -0.6), thrust: 0 },
    { id: "sideFR", pos: v3(1.10, 0.22, +0.95), jet: v3(0, 0.8, +0.6), thrust: 0 },
    { id: "sideRL", pos: v3(-1.10, 0.22, -0.95), jet: v3(0, 0.8, -0.6), thrust: 0 },
    { id: "sideRR", pos: v3(-1.10, 0.22, +0.95), jet: v3(0, 0.8, +0.6), thrust: 0 },
    // Rear diffuser nozzles: jet shoots backward (-X)
    { id: "rear1", pos: v3(-2.22, -0.14, -0.36), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear2", pos: v3(-2.22, -0.14, -0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear3", pos: v3(-2.22, -0.14, +0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear4", pos: v3(-2.22, -0.14, +0.36), jet: v3(-1, 0, 0), thrust: 0 },
  ];

  let phase = "READY";
  let holdStartTime = -1;
  let releaseTime = -1;
  let touchdownTime = -1;
  let maxImpactForce = 0;
  const sHold = ramp.L - 2.35; // target stop near lip (~26.1 m, theta ~ 111.5 deg)
  const dt = 1 / 120;

  for (let step = 0; step <= 16 * 120; step++) {
    const t = step * dt;
    let Fworld = v3(0, -mass * g, 0);
    let Tlocal = v3(0, 0, 0);

    function applyWorldForceAtLocalPoint(Fw, rLocal) {
      Fworld = add(Fworld, Fw);
      const Flocal = qRot(qConj(quat), Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }
    function applyLocalForceAtLocalPoint(Flocal, rLocal) {
      const Fw = qRot(quat, Flocal);
      Fworld = add(Fworld, Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }

    const carFwd = qRot(quat, v3(1, 0, 0));
    const carUp = qRot(quat, v3(0, 1, 0));
    const carRight = qRot(quat, v3(0, 0, 1));
    const omegaWorld = qRot(quat, omegaLocal);

    const cpCenter = ramp.closestPoint(pos.x, pos.y, pos.z);
    const sCar = cpCenter.s;
    const speedAlongTangent = vel.x * cpCenter.tx + vel.y * cpCenter.ty;

    // Flight Controller
    let fanPower = 0;
    let driveForceCmd = 0;
    let brakeForceCmd = 0;
    for (const n of nozzles) n.thrust = 0;

    if (phase === "READY") {
      fanPower = 0.5;
      brakeForceCmd = 15000;
      if (t >= 0.6) phase = "CLIMB";
    }
    if (phase === "CLIMB") {
      fanPower = 1.0;
      const distToHold = sHold - sCar;
      // Target speed profile
      const vPeak = 16.5 * driveScale;
      const vTarget = distToHold > 0 ? Math.min(vPeak, Math.sqrt(2 * 9.5 * Math.max(0, distToHold)) + 0.35) : 0;
      const vErr = vTarget - speedAlongTangent;
      // Gravity compensation along slope + speed error control
      const maxMotorForce = 34000 * Math.pow(driveScale, 1.35);
      if (distToHold <= 0.15 && Math.abs(speedAlongTangent) < 0.8) {
        phase = "HOLD";
        holdStartTime = t;
      } else if (vErr >= -0.3) {
        const gravComp = mass * g * Math.max(0, cpCenter.ty);
        driveForceCmd = Math.min(maxMotorForce, gravComp * Math.min(1, driveScale * 1.05) + 6500 * vErr);
      } else {
        brakeForceCmd = Math.min(45000, -9000 * vErr);
      }
      // If car fell off ramp during climb
      if (cpCenter.dist > 1.35 || (sCar > 8 && speedAlongTangent < -2.5)) {
        phase = "FALLING_FAIL";
      }
    }
    if (phase === "HOLD") {
      fanPower = 1.0;
      // Hold position at sHold with brakes + slight motor hold
      const posErr = sHold - sCar;
      const holdF = mass * g * cpCenter.ty + 22000 * posErr - 16000 * speedAlongTangent;
      const maxMotorForce = 34000 * Math.pow(driveScale, 1.35);
      if (holdF > 0) driveForceCmd = Math.min(maxMotorForce, holdF);
      else brakeForceCmd = Math.min(45000, -holdF);

      if (cpCenter.dist > 1.3) phase = "FALLING_FAIL";
      if (t - holdStartTime >= 2.0) {
        phase = "AIRBORNE";
        releaseTime = t;
      }
    }
    if (phase === "AIRBORNE") {
      fanPower = 0.0;
      const dtRel = t - releaseTime;
      const scaleT = totalThrusterN / (6500 * 9.81);

      if (dtRel < 0.34) {
        // Release push off lip: rear nozzles push car forward (+X local = away from ramp -X and up),
        // front downward nozzles pulse to pitch car from 112 deg to 180 deg (horizontal belly-up facing -X)
        const rearEach = 4200 * scaleT;
        nozzles[8].thrust = nozzles[9].thrust = nozzles[10].thrust = nozzles[11].thrust = rearEach;
        const frontPitchEach = 6200 * scaleT;
        nozzles[0].thrust = nozzles[1].thrust = frontPitchEach;
      } else {
        // 3D Attitude + Descent Controller using ONLY nozzle thrusts!
        // Target orientation: carFwd = (-1, 0, 0), carUp = (0, +1, 0), carRight = (0, 0, -1)
        // Compute world UP (0,1,0) and target FWD (-1,0,0) in car local frame:
        const upLocal = qRot(qConj(quat), v3(0, 1, 0));
        const targetFwdLocal = qRot(qConj(quat), v3(-1, 0, 0));

        // Roll error around local X: angle of upLocal in YZ plane from +Y
        let rollErr = Math.atan2(upLocal.z, upLocal.y);
        // Bias initial inverted roll near +-pi to roll consistently in positive X direction
        if (rollErr < -2.4) rollErr += 2 * Math.PI;
        // Pitch error around local Z:
        const pitchErr = Math.atan2(-upLocal.x, Math.hypot(upLocal.y, upLocal.z));
        // Yaw error around local Y:
        const yawErr = Math.atan2(-targetFwdLocal.z, targetFwdLocal.x);

        const tauRollCmd = (3800 * rollErr - 1350 * omegaLocal.x) * (mass / 2000);
        const tauPitchCmd = (6500 * pitchErr - 2400 * omegaLocal.z) * (mass / 2000);
        const tauYawCmd = (3200 * yawErr - 1400 * omegaLocal.y) * (mass / 2000);

        // Vertical braking & hover once upright-ish (carUp.y > 0.35)
        let liftCmd = 0;
        if (carUp.y > 0.35) {
          // Target vertical velocity profile to hover briefly at y = 0.95 m then descend at -0.9 m/s
          let vTargetY = -1.0;
          if (pos.y > 1.35) {
            // Brake toward hover at y = 1.15 m
            const hAboveHover = Math.max(0, pos.y - 1.15);
            vTargetY = -Math.sqrt(2 * 5.8 * hAboveHover);
          } else if (dtRel < 2.25) {
            // Brief hover at y ~ 1.05 m
            vTargetY = 1.5 * (1.05 - pos.y);
          } else {
            // Gentle touchdown
            vTargetY = -1.1;
          }
          const ayCmd = g + 9.5 * (vTargetY - vel.y);
          liftCmd = Math.max(0, (mass * ayCmd) / Math.max(0.5, carUp.y));
        }

        // Allocate roll torque while inverted/rolling using side attitude jets + corner jets
        if (tauRollCmd > 0) {
          const fSide = Math.min(9000, tauRollCmd * 0.55) * scaleT;
          nozzles[5].thrust = nozzles[7].thrust = fSide; // sideFR, sideRR
          nozzles[0].thrust += fSide * 0.65; // downFL
          nozzles[2].thrust += fSide * 0.65; // downRL
        } else {
          const fSide = Math.min(9000, -tauRollCmd * 0.55) * scaleT;
          nozzles[4].thrust = nozzles[6].thrust = fSide; // sideFL, sideRL
          nozzles[1].thrust += fSide * 0.65; // downFR
          nozzles[3].thrust += fSide * 0.65; // downRR
        }

        // Allocate lift + pitch + fine roll across the 4 corner downward nozzles
        const baseDown = (liftCmd * 0.25) * scaleT;
        const dPitch = (tauPitchCmd / (4 * 1.32)) * scaleT;
        const dRoll = (-tauRollCmd * 0.45 / (4 * 0.74)) * scaleT;
        nozzles[0].thrust = Math.max(0, Math.min(15000 * scaleT, nozzles[0].thrust + baseDown + dPitch - dRoll));
        nozzles[1].thrust = Math.max(0, Math.min(15000 * scaleT, nozzles[1].thrust + baseDown + dPitch + dRoll));
        nozzles[2].thrust = Math.max(0, Math.min(15000 * scaleT, nozzles[2].thrust + baseDown - dPitch - dRoll));
        nozzles[3].thrust = Math.max(0, Math.min(15000 * scaleT, nozzles[3].thrust + baseDown - dPitch + dRoll));

        // Horizontal drift control with rear nozzles if needed
        if (vel.x > -4.8 && pos.x > 1.5 && carFwd.x < -0.5) {
          const rThrust = Math.min(3500, (vel.x + 5.2) * 1800) * scaleT;
          nozzles[8].thrust = nozzles[9].thrust = nozzles[10].thrust = nozzles[11].thrust = Math.max(0, rThrust);
        }
        if (tauYawCmd > 0) {
          nozzles[8].thrust += Math.min(2500, tauYawCmd * 0.5) * scaleT;
        } else {
          nozzles[11].thrust += Math.min(2500, -tauYawCmd * 0.5) * scaleT;
        }
      }

      if (pos.y < 0.43 && carUp.y > 0.85 && dtRel > 1.5) {
        phase = "DRIVE_OUT";
        touchdownTime = t;
      }
    }
    if (phase === "DRIVE_OUT") {
      const dtTouch = t - touchdownTime;
      fanPower = 0.25;
      if (dtTouch < 2.4) {
        // Accelerate out of the smoke in -X (car forward direction!)
        driveForceCmd = 14000;
      } else {
        // Come to a stop
        brakeForceCmd = 18000;
      }
    }

    // Apply Fan Downforce (4 underbody plenum points)
    if (fanPower > 0) {
      const plenumPts = [
        v3(0.85, -0.25, -0.55), v3(0.85, -0.25, +0.55),
        v3(-0.85, -0.25, -0.55), v3(-0.85, -0.25, +0.55)
      ];
      for (const lp of plenumPts) {
        const wp = add(pos, qRot(quat, lp));
        const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
        const surfN = v3(cp.nx, cp.ny, 0);
        const align = dot(carUp, surfN);
        if (cp.dist > -0.2 && cp.dist < 1.15 && align > 0.35) {
          const seal = Math.max(0, 1 - Math.pow(cp.dist / 1.10, 2)) * align;
          const fMag = 0.25 * fanPower * maxDownforceN * seal;
          applyWorldForceAtLocalPoint(scale(surfN, -fMag), lp);
        }
      }
    }

    // Apply 4-wheel suspension & tire grip
    const restLen = 0.22, wheelRad = 0.35;
    for (const w of wheels) {
      const rLocal = v3(w.lx, w.ly, w.lz);
      const wp = add(pos, qRot(quat, rLocal));
      const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
      const surfN = v3(cp.nx, cp.ny, 0);
      const surfT = v3(cp.tx, cp.ty, 0);
      const surfB = v3(0, 0, 1);
      const align = dot(carUp, surfN);
      const comp = (restLen + wheelRad) - cp.dist;
      w.comp = Math.max(0, comp);
      if (comp > 0 && align > 0.2) {
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, rLocal)));
        const vN = dot(vPoint, surfN);
        const kSpring = 140000 * (mass / 2000);
        const kDamp = 15000 * (mass / 2000);
        let Fn = Math.max(0, kSpring * comp - kDamp * vN);
        if (comp > 0.19) {
          Fn += 1800000 * (comp - 0.19);
        }
        if (Fn > maxImpactForce) maxImpactForce = Fn;

        // Tire longitudinal direction along surface
        const fwdSign = dot(carFwd, surfT) >= 0 ? 1 : -1;
        const tireFwd = scale(surfT, fwdSign);
        const vLong = dot(vPoint, tireFwd);
        const vLat = dot(vPoint, surfB);

        const mu = 1.25;
        const maxFriction = mu * Fn;
        let Flong = 0.25 * driveForceCmd;
        if (brakeForceCmd > 0) {
          Flong -= Math.min(0.25 * brakeForceCmd, Math.abs(vLong) * 18000) * Math.sign(vLong || 0);
        }
        // Rolling damping
        Flong -= 120 * vLong;
        Flong = Math.max(-maxFriction, Math.min(maxFriction, Flong));

        // Lateral grip + centerline steering
        const zTarget = 0;
        const yawAlign = dot(carFwd, surfB);
        let Flat = -28000 * vLat - (w.lx > 0 ? (12000 * wp.z + 18000 * yawAlign * fwdSign) : 0);
        const remF = Math.sqrt(Math.max(0, maxFriction * maxFriction - Flong * Flong));
        Flat = Math.max(-remF, Math.min(remF, Flat));

        const Fwheel = add(scale(surfN, Fn), add(scale(tireFwd, Flong), scale(surfB, Flat)));
        applyWorldForceAtLocalPoint(Fwheel, rLocal);
      }
    }

    // Apply chassis/roof/bumper impact if hitting ground/ramp
    const hullCheckPts = [
      v3(2.2, 0.0, 0), v3(-2.2, 0.0, 0), v3(0, 0.62, 0),
      v3(1.1, 0.55, -0.7), v3(1.1, 0.55, 0.7), v3(-1.1, 0.55, -0.7), v3(-1.1, 0.55, 0.7)
    ];
    for (const hp of hullCheckPts) {
      const wp = add(pos, qRot(quat, hp));
      const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
      if (cp.dist < 0.05) {
        const pen = 0.05 - cp.dist;
        const surfN = v3(cp.nx, cp.ny, 0);
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, hp)));
        const vN = dot(vPoint, surfN);
        const Fimp = Math.max(0, 900000 * pen - 35000 * Math.min(0, vN));
        if (Fimp > maxImpactForce) maxImpactForce = Fimp;
        applyWorldForceAtLocalPoint(scale(surfN, Fimp), hp);
      }
    }

    // Apply Thrusters
    for (const n of nozzles) {
      if (n.thrust > 0) {
        applyLocalForceAtLocalPoint(scale(n.jet, -n.thrust), n.pos);
      }
    }

    // Integrate linear motion
    vel = add(vel, scale(Fworld, dt / mass));
    pos = add(pos, scale(vel, dt));

    // Integrate rotational motion (Euler equations in body frame)
    const Iw = v3(Ilocal.x * omegaLocal.x, Ilocal.y * omegaLocal.y, Ilocal.z * omegaLocal.z);
    const gyro = cross(omegaLocal, Iw);
    const alphaLocal = v3(
      (Tlocal.x - gyro.x) / Ilocal.x,
      (Tlocal.y - gyro.y) / Ilocal.y,
      (Tlocal.z - gyro.z) / Ilocal.z
    );
    omegaLocal = add(omegaLocal, scale(alphaLocal, dt));
    // Slight aero angular damping
    omegaLocal = scale(omegaLocal, 0.998);

    const dq = qMul(quat, { x: 0.5 * omegaLocal.x * dt, y: 0.5 * omegaLocal.y * dt, z: 0.5 * omegaLocal.z * dt, w: 0 });
    quat = qNorm({ x: quat.x + dq.x, y: quat.y + dq.y, z: quat.z + dq.z, w: quat.w + dq.w });

    if (step % 120 === 0 || (t >= 8.0 && t <= 12.0 && step % 30 === 0)) {
      const pitchDeg = Math.atan2(carFwd.y, Math.hypot(carFwd.x, carFwd.z)) * RAD;
      console.log(
        `t=${t.toFixed(2)}s [${phase}] pos=(${pos.x.toFixed(2)}, ${pos.y.toFixed(2)}) vel=(${vel.x.toFixed(2)}, ${vel.y.toFixed(2)}) carUp.y=${carUp.y.toFixed(2)} pitch=${pitchDeg.toFixed(1)}° s=${sCar.toFixed(1)}`
      );
    }
  }
  console.log(`=== Max Impact Force: ${(maxImpactForce/1000).toFixed(1)} kN | Final phase: ${phase} ===\n`);
}

console.log("--- TEST 1: DEFAULT RUN ---");
runTest({});
'

