// Check forces at s=26.5 in HOLD with maxDownforceKg = 600 vs 4700
// Wait: on a concave curve, the front wheel normal n_F and rear wheel normal n_R differ by angle 2*a/R!
// And tireFwd at the front wheel is t_F (pointing up-left), while at the rear wheel it is t_R!
// Notice that t_F + t_R has an OUTWARD (-N) component of 2 * sin(a/R) * Flong!
// When Flong > 0 (driving forward up a concave curve), the front and rear tires pushing along the tangent of a concave curve produce a component pressing INTO the curve of Flong * (a/R), PLUS the chord geometry!
console.log("Chord sagitta a^2 / (2R) =", (1.38*1.38 / (2 * 12)).toFixed(4), "m");
'

args.command:
node -e '
// Quick print of LOW_DOWNFORCE with maxDownforceKg = 600
const DEG = Math.PI / 180;
const THETA_MAX = 115 * DEG, TARGET_HEIGHT = 20.0, RAMP_WIDTH = 6.2;
function rawCurvatureWeight(u) {
  const u0 = 0.12;
  const entry = u < u0 ? (u / u0) * (u / u0) * (3 - 2 * (u / u0)) : 1.0;
  return entry * (1.35 - 0.65 * Math.pow(Math.max(0, (u - 0.35) / 0.65), 1.2));
}
const N = 2000, theta = new Float64Array(N + 1);
let intF = 0;
for (let i = 1; i <= N; i++) { intF += rawCurvatureWeight((i - 0.5) / N) / N; theta[i] = intF; }
for (let i = 0; i <= N; i++) theta[i] = (theta[i] / intF) * THETA_MAX;
let uy = 0;
for (let i = 1; i <= N; i++) uy += Math.sin(0.5 * (theta[i - 1] + theta[i])) / N;
const L = TARGET_HEIGHT / uy, ds = L / N;
const xs = new Float64Array(N + 1), ys = new Float64Array(N + 1), kappas = new Float64Array(N + 1);
for (let i = 1; i <= N; i++) {
  const th = 0.5 * (theta[i - 1] + theta[i]);
  xs[i] = xs[i - 1] + Math.cos(th) * ds;
  ys[i] = ys[i - 1] + Math.sin(th) * ds;
  kappas[i] = (theta[i] - theta[i - 1]) / ds;
}
function sampleAtS(s) {
  if (s <= 0) return { s, x: s, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1 };
  const sc = Math.min(L, s), idxF = sc / ds, i0 = Math.min(N - 1, Math.floor(idxF)), f = idxF - i0;
  const th = theta[i0] + f * (theta[i0 + 1] - theta[i0]);
  const ka = kappas[i0] + f * (kappas[i0 + 1] - kappas[i0]);
  const x = xs[i0] + f * (xs[i0 + 1] - xs[i0]), y = ys[i0] + f * (ys[i0 + 1] - ys[i0]);
  return { s: sc, x, y, theta: th, kappa: ka, tx: Math.cos(th), ty: Math.sin(th), nx: -Math.sin(th), ny: Math.cos(th) };
}
// Check at s = 21 (theta = 90 deg, vertical wall):
// At theta = 90 deg, gravity normal W_perp = 0, gravity parallel W_par = 19,620 N!
// Why did the car climb the vertical wall at s=21 with maxDownforceKg=850?
// Because at s=15..21, the car had speed v = 11.5 m/s, and on a curve of radius R=12.5m,
// centrifugal acceleration v^2 / R = 132 / 12.5 = 10.5 m/s^2 -> centrifugal normal force = 21,000 N!
// Wait: why did it hold at s=26.5 when v=0?
// Because at s=26.5, front wheel is at s=27.9 (nx=-0.910, ny=-0.415) and rear wheel is at s=25.1 (nx=-0.958, ny=-0.285).
// Notice that tireFwd at the rear wheel is (tx_R, ty_R) = (-0.285, +0.958), while normal at front wheel is (-0.910, -0.415)!
// The rear wheel driving forward pushes the car body into the front wheel normal (-0.285*-0.910 + 0.958*-0.415 = -0.259 - 0.397 = -0.656?) No, +0.259 - 0.397 = -0.138 (INTO the front wheel)!
// Yes! Because the ramp is curved by 13 degrees between the rear axle and front axle, pushing forward along the rear tangent has a sin(13 deg) = 0.225 component INTO the front ramp surface!
console.log("sin(wheelbase / R) =", Math.sin(2.76 / 12).toFixed(3));
'

