        const vN = dot(vPoint, surfN);
        const Fimp = Math.max(0, 900000 * pen - 35000 * Math.min(0, vN));
        if (Fimp > maxHullForce) maxHullForce = Fimp;
        applyWorldForceAtLocalPoint(scale(surfN, Fimp), hp);
      }
      if (wp.y < 0.04) {
        const pen = 0.04 - wp.y;
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, hp)));
        const Fimp = Math.max(0, 900000 * pen - 35000 * Math.min(0, vPoint.y));
        if (Fimp > maxHullForce) maxHullForce = Fimp;
        applyWorldForceAtLocalPoint(v3(0, Fimp, 0), hp);
