const DEG = Math.PI / 180;
const RAD = 180 / Math.PI;
const THETA_MAX = 115 * DEG;
const TARGET_HEIGHT = 20.0;
const RAMP_WIDTH = 6.2;

function rawCurvatureWeight(u) {
  const u0 = 0.12;
  const entry = u < u0 ? (u / u0) * (u / u0) * (3 - 2 * (u / u0)) : 1.0;
  const profile = 1.35 - 0.65 * Math.pow(Math.max(0, (u - 0.35) / 0.65), 1.2);
  return entry * profile;
}

function buildRampTable() {
  const N = 2000;
  const theta = new Float64Array(N + 1);
  let intF = 0;
  for (let i = 1; i <= N; i++) {
    intF += rawCurvatureWeight((i - 0.5) / N) / N;
    theta[i] = intF;
  }
  for (let i = 0; i <= N; i++) theta[i] = (theta[i] / intF) * THETA_MAX;
  let ux = 0, uy = 0;
  for (let i = 1; i <= N; i++) {
    const th = 0.5 * (theta[i - 1] + theta[i]);
    ux += Math.cos(th) / N;
    uy += Math.sin(th) / N;
  }
  const L = TARGET_HEIGHT / uy;
  const ds = L / N;
  const xs = new Float64Array(N + 1);
  const ys = new Float64Array(N + 1);
  const kappas = new Float64Array(N + 1);
  for (let i = 1; i <= N; i++) {
    const th = 0.5 * (theta[i - 1] + theta[i]);
    xs[i] = xs[i - 1] + Math.cos(th) * ds;
    ys[i] = ys[i - 1] + Math.sin(th) * ds;
    kappas[i] = (theta[i] - theta[i - 1]) / ds;
  }
  kappas[0] = 0;

  function sampleAtS(s) {
    if (s <= 0) return { s, x: s, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1 };
    const sc = Math.min(L, s);
    const idxF = sc / ds;
    const i0 = Math.min(N - 1, Math.floor(idxF));
    const f = idxF - i0;
    const th = theta[i0] + f * (theta[i0 + 1] - theta[i0]);
    const ka = kappas[i0] + f * (kappas[i0 + 1] - kappas[i0]);
    const x = xs[i0] + f * (xs[i0 + 1] - xs[i0]);
    const y = ys[i0] + f * (ys[i0 + 1] - ys[i0]);
    const tx = Math.cos(th), ty = Math.sin(th);
    return { s: sc, x, y, theta: th, kappa: ka, tx, ty, nx: -ty, ny: tx };
  }

  function closestPoint(px, py, pz) {
    if (Math.abs(pz) > RAMP_WIDTH * 0.5 || (px <= 0 && py < 3.5)) {
      return { s: px, x: px, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1, dist: py, distT: 0, onRamp: false };
    }
    let bestI = 0, bestD2 = 1e9;
    const step = 25;
    for (let i = 0; i <= N; i += step) {
      const dx = px - xs[i], dy = py - ys[i];
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; bestI = i; }
    }
    const iStart = Math.max(0, bestI - step), iEnd = Math.min(N, bestI + step);
    for (let i = iStart; i <= iEnd; i++) {
      const dx = px - xs[i], dy = py - ys[i];
      const d2 = dx * dx + dy * dy;
      if (d2 < bestD2) { bestD2 = d2; bestI = i; }
    }
    let s = bestI * ds;
    for (let iter = 0; iter < 3; iter++) {
      const sp = sampleAtS(s);
      const dx = px - sp.x, dy = py - sp.y;
      const projT = dx * sp.tx + dy * sp.ty;
      const projN = dx * sp.nx + dy * sp.ny;
      const denom = Math.max(0.2, 1 - sp.kappa * projN);
      s = Math.max(0, Math.min(L, s + projT / denom));
    }
    const sp = sampleAtS(s);
    const dx = px - sp.x, dy = py - sp.y;
    const distN = dx * sp.nx + dy * sp.ny;
    const distT = dx * sp.tx + dy * sp.ty;
    if (px < 1.5 && py < 1.5 && py < Math.abs(distN)) {
      return { s: px, x: px, y: 0, theta: 0, kappa: 0, tx: 1, ty: 0, nx: 0, ny: 1, dist: py, distT: 0, onRamp: false };
    }
    return { ...sp, dist: distN, distT, onRamp: s > 0 && s <= L };
  }

  return { L, sampleAtS, closestPoint };
}

const ramp = buildRampTable();

function v3(x=0,y=0,z=0){ return {x,y,z}; }
function add(a,b){ return {x:a.x+b.x, y:a.y+b.y, z:a.z+b.z}; }
function scale(a,s){ return {x:a.x*s, y:a.y*s, z:a.z*s}; }
function dot(a,b){ return a.x*b.x + a.y*b.y + a.z*b.z; }
function cross(a,b){ return {x:a.y*b.z-a.z*b.y, y:a.z*b.x-a.x*b.z, z:a.x*b.y-a.y*b.x}; }
function qMul(a,b){
  return {
    x: a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
    y: a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
    z: a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w,
    w: a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z
  };
}
function qConj(q){ return {x:-q.x, y:-q.y, z:-q.z, w:q.w}; }
function qNorm(q){
  const l = Math.hypot(q.x,q.y,q.z,q.w)||1;
  return {x:q.x/l, y:q.y/l, z:q.z/l, w:q.w/l};
}
function qRot(q, v){
  const u = {x:q.x, y:q.y, z:q.z};
  const s = q.w;
  const d = dot(u, v);
  const c = cross(u, v);
  return {
    x: 2*d*u.x + (s*s - dot(u,u))*v.x + 2*s*c.x,
    y: 2*d*u.y + (s*s - dot(u,u))*v.y + 2*s*c.y,
    z: 2*d*u.z + (s*s - dot(u,u))*v.z + 2*s*c.z
  };
}

function runTest(name, cfg, verbose = false) {
  const mass = cfg.mass ?? 2000;
  const maxDownforceN = (cfg.maxDownforceKg ?? 4700) * 9.81;
  const driveScale = (cfg.entrySpeed ?? 100) / 100;
  const totalThrusterN = (cfg.thrusterForceKg ?? 6500) * 9.81;
  const g = cfg.gravity ?? 9.81;

  const Ilocal = { x: 0.48 * mass, y: 1.90 * mass, z: 1.65 * mass };
  const restLen = 0.22, wheelRad = 0.35, mountLy = 0.12;
  const kSpring0 = 140000 * (mass / 2000);
  const staticComp = (mass * g) / (4 * kSpring0);
  let pos = v3(-6.5, (restLen + wheelRad - mountLy) - staticComp, 0);
  let vel = v3(0, 0, 0);
  let quat = { x: 0, y: 0, z: 0, w: 1 };
  let omegaLocal = v3(0, 0, 0);

  const wheels = [
    { name: "FL", lx: 1.38, ly: mountLy, lz: -0.84, comp: staticComp },
    { name: "FR", lx: 1.38, ly: mountLy, lz: +0.84, comp: staticComp },
    { name: "RL", lx: -1.38, ly: mountLy, lz: -0.84, comp: staticComp },
    { name: "RR", lx: -1.38, ly: mountLy, lz: +0.84, comp: staticComp },
  ];

  const nozzles = [
    { id: "downFL", pos: v3(1.32, -0.22, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downFR", pos: v3(1.32, -0.22, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRL", pos: v3(-1.32, -0.22, -0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "downRR", pos: v3(-1.32, -0.22, +0.74), jet: v3(0, -1, 0), thrust: 0 },
    { id: "sideFL", pos: v3(1.10, 0.22, -0.92), jet: v3(0, 0.96, -0.28), thrust: 0 },
    { id: "sideFR", pos: v3(1.10, 0.22, +0.92), jet: v3(0, 0.96, +0.28), thrust: 0 },
    { id: "sideRL", pos: v3(-1.10, 0.22, -0.92), jet: v3(0, 0.96, -0.28), thrust: 0 },
    { id: "sideRR", pos: v3(-1.10, 0.22, +0.92), jet: v3(0, 0.96, +0.28), thrust: 0 },
    { id: "rear1", pos: v3(-2.22, -0.10, -0.36), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear2", pos: v3(-2.22, -0.10, -0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear3", pos: v3(-2.22, -0.10, +0.12), jet: v3(-1, 0, 0), thrust: 0 },
    { id: "rear4", pos: v3(-2.22, -0.10, +0.36), jet: v3(-1, 0, 0), thrust: 0 },
  ];

  let phase = "READY";
  let holdStartTime = -1;
  let releaseTime = -1;
  let hoverStartTime = -1;
  let touchdownTime = -1;
  let touchdownX = 0;
  let maxWheelForce = 0;
  let maxHullForce = 0;
  let maxReachedS = 0;
  const sHold = ramp.L - 1.95;
  const dt = 1 / 120;

  for (let step = 0; step <= 16 * 120; step++) {
    const t = step * dt;
    let Fworld = v3(0, -mass * g, 0);
    let Tlocal = v3(0, 0, 0);

    function applyWorldForceAtLocalPoint(Fw, rLocal) {
      Fworld = add(Fworld, Fw);
      const Flocal = qRot(qConj(quat), Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }
    function applyLocalForceAtLocalPoint(Flocal, rLocal) {
      const Fw = qRot(quat, Flocal);
      Fworld = add(Fworld, Fw);
      Tlocal = add(Tlocal, cross(rLocal, Flocal));
    }

    const carFwd = qRot(quat, v3(1, 0, 0));
    const carUp = qRot(quat, v3(0, 1, 0));
    const omegaWorld = qRot(quat, omegaLocal);

    const cpCenter = ramp.closestPoint(pos.x, pos.y, pos.z);
    const sCar = cpCenter.s;
    if (sCar > maxReachedS) maxReachedS = sCar;
    const speedAlongTangent = vel.x * cpCenter.tx + vel.y * cpCenter.ty;

    let fanPower = 0;
    let driveForceCmd = 0;
    let brakeForceCmd = 0;
    let steerBias = 0;
    for (const n of nozzles) n.thrust = 0;

    if (phase === "READY") {
      fanPower = Math.min(1.0, t / 0.7);
      brakeForceCmd = 15000;
      if (t >= 0.8) phase = "CLIMB";
    }
    if (phase === "CLIMB") {
      fanPower = 1.0;
      const distToHold = sHold - sCar;
      const vPeak = 13.8 * driveScale;
      const vTarget = distToHold > 0 ? Math.min(vPeak, Math.sqrt(2 * 6.8 * Math.max(0, distToHold)) + 0.25) : 0;
      const vErr = vTarget - speedAlongTangent;
      const maxMotorForce = 33000 * Math.pow(driveScale, 1.4);
      if (distToHold <= 0.22 && Math.abs(speedAlongTangent) < 0.85 && cpCenter.dist < 0.52) {
        phase = "HOLD";
        holdStartTime = t;
      } else if (vErr >= -0.20) {
        const gravComp = mass * g * Math.max(0, cpCenter.ty);
        driveForceCmd = Math.min(maxMotorForce, gravComp * Math.min(1, driveScale * 1.05) + 7500 * vErr);
      } else {
        brakeForceCmd = Math.min(48000, -12000 * vErr);
      }
      if (cpCenter.dist > 0.65) {
        phase = "FALLING_FAIL";
        omegaLocal.x += 0.9;
        omegaLocal.y += 0.5;
      } else if (sCar > 5 && speedAlongTangent < -0.6) {
        steerBias = 0.65;
        if (Math.abs(pos.z) > RAMP_WIDTH * 0.42 || speedAlongTangent < -4.5) {
          phase = "FALLING_FAIL";
          omegaLocal.x += 1.2;
          omegaLocal.y -= 0.7;
        }
      }
    }
    if (phase === "HOLD") {
      fanPower = 1.0;
      const posErr = sHold - sCar;
      const holdF = mass * g * cpCenter.ty + 25000 * posErr - 18000 * speedAlongTangent;
      const maxMotorForce = 33000 * Math.pow(driveScale, 1.4);
      if (holdF > 0) driveForceCmd = Math.min(maxMotorForce, holdF);
      else brakeForceCmd = Math.min(48000, -holdF);

      if (cpCenter.dist > 0.60 || sCar < sHold - 1.2) {
        phase = "FALLING_FAIL";
        omegaLocal.x += 0.9;
      } else if (t - holdStartTime >= 2.0) {
        phase = "AIRBORNE";
        releaseTime = t;
      }
    }
    if (phase === "AIRBORNE") {
      fanPower = 0.0;
      const dtRel = t - releaseTime;
      const scaleT = totalThrusterN / (6500 * 9.81);

      if (dtRel < 0.46) {
        // Stage 1: Push off lip in -X and pitch cleanly from 112.5 deg to 180 deg (horizontal belly-up facing -X)
        const rearEach = dtRel < 0.36 ? 4800 * scaleT : 0;
        nozzles[8].thrust = nozzles[9].thrust = nozzles[10].thrust = nozzles[11].thrust = rearEach;

        const currentTheta = Math.atan2(carFwd.y, carFwd.x);
        let thetaErr = Math.PI - currentTheta;
        if (thetaErr > Math.PI) thetaErr -= 2 * Math.PI;
        if (thetaErr < -Math.PI) thetaErr += 2 * Math.PI;
        const tauZ = (15000 * thetaErr - 4200 * omegaLocal.z) * (mass / 2000);
        if (tauZ > 0) {
          const fP = Math.min(11000, tauZ / (2 * 1.32)) * scaleT;
          nozzles[0].thrust = nozzles[1].thrust = fP;
        } else {
          const fP = Math.min(11000, -tauZ / (2 * 1.32)) * scaleT;
          nozzles[2].thrust = nozzles[3].thrust = fP;
        }
      } else {
        // Stage 2: Critically damped axial roll around local X + downward braking jets to land at foot of ramp (xTarget = -3.0, zTarget = 0.0)
        const xTarget = -3.0;
        const vxTarget = Math.max(-6.5, Math.min(1.5, 0.85 * (xTarget - pos.x)));
        const axCmd = 1.6 * (vxTarget - vel.x);
        const azCmd = 2.0 * (-1.2 * pos.z - vel.z);
        const desiredUpX = carUp.y > 0.70 ? Math.max(-0.16, Math.min(0.22, axCmd / g)) : 0;
        const desiredUpZ = carUp.y > 0.70 ? Math.max(-0.14, Math.min(0.14, azCmd / g)) : 0;
        const desiredUpWorld = qNorm({ x: desiredUpX, y: 1.0, z: desiredUpZ, w: 0 });

        const upLocal = qRot(qConj(quat), desiredUpWorld);
        const targetFwdLocal = qRot(qConj(quat), v3(-1, 0, 0));

        let rollErr = Math.atan2(upLocal.z, upLocal.y);
        if (rollErr < -2.3) rollErr += 2 * Math.PI;
        const pitchErr = -upLocal.x;
        const yawErr = -targetFwdLocal.z;

        const tauRollCmd = (5200 * rollErr - 3800 * omegaLocal.x) * (mass / 2000);
        const tauPitchCmd = (16000 * pitchErr - 4800 * omegaLocal.z) * (mass / 2000);
        const tauYawCmd = (4500 * yawErr - 2000 * omegaLocal.y) * (mass / 2000);

        let liftCmd = 0;
        if (carUp.y > 0.35) {
          let vTargetY = -0.80;
          if (pos.y > 1.20) {
            const hAboveHover = Math.max(0, pos.y - 1.02);
            vTargetY = -Math.sqrt(2 * 6.2 * hAboveHover);
          } else {
            if (hoverStartTime < 0) hoverStartTime = t;
            if (t - hoverStartTime < 0.40) {
              vTargetY = 2.8 * (0.98 - pos.y);
            } else {
              vTargetY = -0.75;
            }
          }
          const ayCmd = g + 11.0 * (vTargetY - vel.y);
          liftCmd = Math.max(0, (mass * ayCmd) / Math.max(0.45, carUp.y));
        }

        if (tauRollCmd > 0) {
          const fSide = Math.min(9500, tauRollCmd * 0.55) * scaleT;
          nozzles[5].thrust = nozzles[7].thrust = fSide;
          nozzles[0].thrust += fSide * 0.60;
          nozzles[2].thrust += fSide * 0.60;
        } else {
          const fSide = Math.min(9500, -tauRollCmd * 0.55) * scaleT;
          nozzles[4].thrust = nozzles[6].thrust = fSide;
          nozzles[1].thrust += fSide * 0.60;
          nozzles[3].thrust += fSide * 0.60;
        }

        const baseDown = (liftCmd * 0.25) * scaleT;
        const dPitch = (tauPitchCmd / (4 * 1.32)) * scaleT;
        const dRoll = (-tauRollCmd * 0.45 / (4 * 0.74)) * scaleT;
        nozzles[0].thrust = Math.max(0, Math.min(15500 * scaleT, nozzles[0].thrust + baseDown + dPitch - dRoll));
        nozzles[1].thrust = Math.max(0, Math.min(15500 * scaleT, nozzles[1].thrust + baseDown + dPitch + dRoll));
        nozzles[2].thrust = Math.max(0, Math.min(15500 * scaleT, nozzles[2].thrust + baseDown - dPitch - dRoll));
        nozzles[3].thrust = Math.max(0, Math.min(15500 * scaleT, nozzles[3].thrust + baseDown - dPitch + dRoll));

        if (tauYawCmd > 0) nozzles[8].thrust += Math.min(2500, tauYawCmd * 0.5) * scaleT;
        else nozzles[11].thrust += Math.min(2500, -tauYawCmd * 0.5) * scaleT;
      }

      if (pos.y < 0.46 && carUp.y > 0.90 && dtRel > 1.5) {
        phase = "DRIVE_OUT";
        touchdownTime = t;
        touchdownX = pos.x;
      }
    }
    if (phase === "DRIVE_OUT") {
      const dtTouch = t - touchdownTime;
      fanPower = 0.25;
      if (dtTouch < 0.25) {
        brakeForceCmd = 6000;
      } else if (dtTouch < 2.6) {
        driveForceCmd = 14000;
      } else {
        brakeForceCmd = 18000;
      }
    }

    if (fanPower > 0) {
      const plenumPts = [
        v3(0.85, -0.15, -0.55), v3(0.85, -0.15, +0.55),
        v3(-0.85, -0.15, -0.55), v3(-0.85, -0.15, +0.55)
      ];
      for (const lp of plenumPts) {
        const wp = add(pos, qRot(quat, lp));
        const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
        const surfN = v3(cp.nx, cp.ny, 0);
        const align = dot(carUp, surfN);
        if (cp.dist > -0.2 && cp.dist < 0.58 && align > 0.35) {
          const seal = Math.max(0, 1 - Math.pow(Math.max(0, cp.dist - 0.15) / 0.43, 2)) * align;
          const fMag = 0.25 * fanPower * maxDownforceN * seal;
          applyWorldForceAtLocalPoint(scale(surfN, -fMag), lp);
        }
      }
    }

    for (const w of wheels) {
      const rLocal = v3(w.lx, w.ly, w.lz);
      const wp = add(pos, qRot(quat, rLocal));
      const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
      const surfN = v3(cp.nx, cp.ny, 0);
      const surfT = v3(cp.tx, cp.ty, 0);
      const surfB = v3(0, 0, 1);
      const align = dot(carUp, surfN);
      const sagitta = 0.5 * cp.kappa * (w.lx * w.lx);
      const comp = (restLen + wheelRad - sagitta) - cp.dist;
      w.comp = Math.max(0, comp);
      if (comp > 0 && align > 0.2) {
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, rLocal)));
        const vN = dot(vPoint, surfN);
        const kSpring = 140000 * (mass / 2000);
        const kDamp = 15000 * (mass / 2000);
        let Fn = Math.max(0, kSpring * comp - kDamp * vN);
        if (comp > 0.20) Fn += 1800000 * (comp - 0.20);
        if (Fn > maxWheelForce) maxWheelForce = Fn;

        const fwdSign = dot(carFwd, surfT) >= 0 ? 1 : -1;
        const tireFwd = scale(surfT, fwdSign);
        const vLong = dot(vPoint, tireFwd);
        const vLat = dot(vPoint, surfB);

        const mu = 1.05;
        const maxFriction = mu * Fn;
        let Flong = 0.25 * driveForceCmd;
        if (brakeForceCmd > 0) {
          Flong -= Math.min(0.25 * brakeForceCmd, Math.abs(vLong) * 18000) * Math.sign(vLong || 0);
        }
        Flong -= 120 * vLong;
        Flong = Math.max(-maxFriction, Math.min(maxFriction, Flong));

        const yawAlign = dot(carFwd, surfB);
        let Flat = -28000 * vLat - (w.lx > 0 ? (12000 * (wp.z - steerBias * 5) + 18000 * yawAlign * fwdSign) : 0);
        const remF = Math.sqrt(Math.max(0, maxFriction * maxFriction - Flong * Flong));
        Flat = Math.max(-remF, Math.min(remF, Flat));

        const Fwheel = add(scale(surfN, Fn), add(scale(tireFwd, Flong), scale(surfB, Flat)));
        applyWorldForceAtLocalPoint(Fwheel, rLocal);
      }
    }

    const hullCheckPts = [
      v3(2.2, 0.0, 0), v3(-2.2, 0.0, 0), v3(0, 0.62, 0),
      v3(1.1, 0.55, -0.7), v3(1.1, 0.55, 0.7), v3(-1.1, 0.55, -0.7), v3(-1.1, 0.55, 0.7),
      v3(1.8, -0.25, -0.9), v3(1.8, -0.25, 0.9), v3(-1.8, -0.25, -0.9), v3(-1.8, -0.25, 0.9)
    ];
    for (const hp of hullCheckPts) {
      const wp = add(pos, qRot(quat, hp));
      const cp = ramp.closestPoint(wp.x, wp.y, wp.z);
      // Only collide with the ramp if the point is within 0.6m of the ramp slab thickness (not 2m behind the slab!)
      if (cp.onRamp && cp.dist < 0.04 && cp.dist > -0.65 && Math.abs(wp.z) <= RAMP_WIDTH * 0.5) {
        const pen = 0.04 - cp.dist;
        const surfN = v3(cp.nx, cp.ny, 0);
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, hp)));
        const vN = dot(vPoint, surfN);
        const Fimp = Math.max(0, 900000 * pen - 35000 * Math.min(0, vN));
        if (Fimp > maxHullForce) maxHullForce = Fimp;
        applyWorldForceAtLocalPoint(scale(surfN, Fimp), hp);
      }
      if (wp.y < 0.04) {
        const pen = 0.04 - wp.y;
        const vPoint = add(vel, cross(omegaWorld, qRot(quat, hp)));
        const Fimp = Math.max(0, 900000 * pen - 35000 * Math.min(0, vPoint.y));
        if (Fimp > maxHullForce) maxHullForce = Fimp;
        applyWorldForceAtLocalPoint(v3(0, Fimp, 0), hp);
      }
    }

    for (const n of nozzles) {
      if (n.thrust > 0) applyLocalForceAtLocalPoint(scale(n.jet, -n.thrust), n.pos);
    }

    vel = add(vel, scale(Fworld, dt / mass));
    pos = add(pos, scale(vel, dt));

    const Iw = v3(Ilocal.x * omegaLocal.x, Ilocal.y * omegaLocal.y, Ilocal.z * omegaLocal.z);
    const gyro = cross(omegaLocal, Iw);
    const alphaLocal = v3(
      (Tlocal.x - gyro.x) / Ilocal.x,
      (Tlocal.y - gyro.y) / Ilocal.y,
      (Tlocal.z - gyro.z) / Ilocal.z
    );
    omegaLocal = add(omegaLocal, scale(alphaLocal, dt));
    omegaLocal = scale(omegaLocal, 0.998);

    const dq = qMul(quat, { x: 0.5 * omegaLocal.x * dt, y: 0.5 * omegaLocal.y * dt, z: 0.5 * omegaLocal.z * dt, w: 0 });
    quat = qNorm({ x: quat.x + dq.x, y: quat.y + dq.y, z: quat.z + dq.z, w: quat.w + dq.w });

    if (verbose && step % 60 === 0) {
      console.log(
        `t=${t.toFixed(2)}s [${phase}] pos=(${pos.x.toFixed(2)}, ${pos.y.toFixed(2)}, ${pos.z.toFixed(2)}) vel=(${vel.x.toFixed(2)}, ${vel.y.toFixed(2)}) carUp=(${carUp.x.toFixed(2)},${carUp.y.toFixed(2)},${carUp.z.toFixed(2)})`
      );
    }
  }
  console.log(`[${name}] Final phase: ${phase} | MaxS: ${maxReachedS.toFixed(1)}m | TouchdownX: ${touchdownX.toFixed(1)}m | MaxWheelF: ${(maxWheelForce/1000).toFixed(1)}kN | MaxHullF: ${(maxHullForce/1000).toFixed(1)}kN`);
}

