      // 1. Pure roll couple tauX across side nozzles (4..7) & corner downward nozzles (0..3)
      if (tauX > 0) {
        const fR = Math.min(10500, tauX / (4 * 0.82)) * scaleT;
        nozzles[5].thrust += fR; nozzles[7].thrust += fR; // sideFR, sideRR (-Fy at +z)
        nozzles[0].thrust += fR; nozzles[2].thrust += fR; // downFL, downRL (+Fy at -z)
      } else {
        const fR = Math.min(10500, -tauX / (4 * 0.82)) * scaleT;
